"""Build the offline HTML manual from verified local application behavior."""
from pathlib import Path
from html import escape
import base64
ROOT=Path(__file__).resolve().parents[1]
sections=[]
def add(id,title,kicker,content): sections.append((id,title,kicker,content))
def shot(file,caption):
    p=ROOT/'screenshots'/file
    if not p.exists(): return ''
    data=base64.b64encode(p.read_bytes()).decode()
    return f'<details class="shot"><summary>展开界面示例 · {escape(caption)}</summary><figure><img loading="lazy" src="data:image/png;base64,{data}" alt="{escape(caption)}"><figcaption>界面示例使用独立测试数据，与正式业务数据无关。{escape(caption)}</figcaption></figure></details>'
def steps(items): return '<ol class="steps">'+''.join('<li>'+i+'</li>' for i in items)+'</ol>'
def note(content,kind='tip'): return f'<div class="callout {kind}">{content}</div>'
def table(headers,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
add('quickstart','第一次使用','01 / START HERE','''<p class="lead">先建立一个客户，再走通一笔报价和订单。整个系统都围绕同一个客户保存业务历史。</p><div class="flow"><span>客户</span><b>→</b><span>商机</span><b>→</b><span>报价</span><b>→</b><span>订单</span><b>→</b><span>供货</span><b>→</b><span>收款 / 出货</span></div>'''+steps(['<strong>启动程序：</strong>在项目文件夹中双击 <code>start.command</code>，保持打开的终端窗口运行。','<strong>打开系统：</strong>在本机浏览器访问 <a href="http://127.0.0.1:5001/" target="_blank" rel="noopener">http://127.0.0.1:5001/</a>。','<strong>登录并修改密码：</strong>管理员账号为 <code>admin</code>，使用初始化时获得的密码；进入「设置 → 修改我的密码」。本指南不保存登录密码。','<strong>建立基础资料：</strong>如果有不同岗位，管理员先创建员工账号；再建立产品和供应商资料。单人使用时，管理员可以完成全部业务。','<strong>开始第一笔业务：</strong>新建客户并添加联系人，记录沟通需求，创建报价，客户确认后转为订单。'])+note('<strong>本地使用：</strong>当前程序只监听本机地址。同一台电脑可切换不同岗位账号；其他电脑不能通过这个地址访问你的系统。关闭网页不会删除数据，退出启动终端或关机后需要重新启动程序。'))
add('roles','账号与角色权限','02 / PEOPLE',table(['角色','主要工作','可访问的业务范围'],[['管理员','账号管理、客户分配、全部业务处理','全部客户和订单，产品及供货成本，操作日志。'],['业务员','客户跟进、商机、报价、订单与出货','本人负责的客户及关联业务；不能登记收款或查看供货成本。'],['采购 / 生产','产品、供应商、执行供货任务','分配给自己的订单产品与任务；不显示订单销售价格、收款及订单附件。'],['财务','到账登记、应收核对、收款更正','订单、收款、相关附件及财务报表。']])+steps(['管理员打开「设置 → 新建账号」，填写登录账号、姓名、角色和初始密码。密码至少 10 位。','员工使用自己的账号登录。看不到某个菜单或操作时，先核对当前角色。','管理员可在设置中启用 / 停用账号、重置密码。管理员不能停用自己。','客户需要转交时，管理员在客户详情点击「编辑资料」，修改负责人并保存。原负责人的未完成关联待办会一并转交。'])+note('第一版的角色在创建账号时指定，界面未提供直接修改已有账号角色的入口。停用账号不会删除已有客户或订单。'))
add('dashboard','每天从工作台开始','03 / DAILY ROUTINE',steps(['查看「我的待办」和逾期数量，优先处理已逾期事项。','完成行动后勾选待办；需要记录沟通结果时，进入对应客户的「记录跟进」。勾选待办本身不会自动生成沟通记录。','临时事项可以点击「添加待办」，填写事项与提醒日期，也可以关联客户。','查看销售漏斗，找出停留在询盘、报价或谈判阶段的机会。','查看按币种列出的订单金额、已收与待收金额，再进入订单核对供货、交期和出货进度。'])+note('工作台按当前账号权限显示数据。个人待办只显示当前登录人的任务；金额按币种分开统计。')+shot('01-dashboard.png','工作台：待办、漏斗、分币种金额与客户列表'))
add('customers','客户、联系人与跟进','04 / CUSTOMERS','<h3>建立客户档案</h3>'+steps(['打开「客户 → 新建客户」，填写公司名称、国家、来源、关注产品、客户类型和主要联系人。','管理员可以选择负责人；业务员创建的客户默认由本人负责。','保存后点击公司名称或「查看详情」，进入客户档案。','在联系人区域点击「添加」，补充采购、财务或其他联系人；已有联系人可单独编辑。'])+'<h3>记录沟通并安排下一步</h3>'+steps(['客户详情点击「记录跟进」，填写沟通内容并选择邮件、电话、WhatsApp、会议或其他渠道。','需要后续提醒时，填写「下一步行动」与「下次跟进日期」。保存后自动为客户负责人创建待办。','在「跟进记录」查看历史沟通；「报价记录」「订单记录」查看该客户的关联业务。','客户资料、询盘文件等可在客户详情的「附件」区域上传。'])+note('<strong>查找与归档：</strong>客户列表支持搜索公司、联系人、邮箱及客户类型筛选。公司名称不区分大小写查重。暂时不用的客户可归档，并在「已归档」页签查看和恢复；历史业务仍保留。')+shot('02-customer.png','客户详情：多联系人、跟进时间线和关联业务'))
add('opportunities','用商机看板推进机会','05 / SALES PIPELINE','<p>同一客户可以有多条商机。建议为不同项目、采购计划或复购需求分别建立商机。</p><div class="flow small"><span>新询盘</span><b>→</b><span>需求确认</span><b>→</b><span>已报价</span><b>→</b><span>样品 / 谈判</span><b>→</b><span>待确认订单</span></div>'+steps(['打开「商机 → 新建商机」，选择客户，填写商机名称、预计金额、币种、下一步行动和预计成交日期。','点击商机卡片，修改阶段、下一步行动与预计成交日期，再保存。当前看板通过点击卡片更新阶段，不使用拖动操作。','要与后续成交关联时，在商机详情点击「创建关联报价」。这份报价转订单后，关联商机会自动标记为赢单。','未成交时选择「丢单」并填写原因；赢单与丢单记录会显示在「已结束商机」区域。'])+note('商机阶段变化不会自动生成跟进待办。如需提醒，请在客户跟进时填写下一步和日期，或在工作台添加待办。')+shot('05-opportunities.png','商机看板：按阶段查看项目和下一步行动'))
add('products','产品与供应商资料','06 / PRODUCTS','<h3>先建立可复用的产品资料</h3>'+steps(['管理员或采购 / 生产人员打开「产品 → 新建产品」。','填写唯一 SKU、产品名称、规格、单位、默认供货方式、参考单位成本和成本币种。','点击产品卡片的「查看资料」，可编辑产品、增加供货来源或上传图片及资料。','第一张上传的产品图片会显示在产品卡片上；产品图片和规格资料也可作为附件下载。'])+'<h3>维护外采与混合供货来源</h3>'+steps(['进入「产品 → 供应商管理」，填写供应商名称、联系人和电话，点击「新增供应商」。','产品详情点击「供货来源」，选择自产或外采；外采时选择供应商，填写参考单位成本。','同一产品可建立多个供货来源。默认方式可以是混合供货，实际数量拆分在销售订单内安排。'])+note('产品参考成本属于内部信息，业务员不会看到。参考成本不会自动成为销售单价，也不会自动分配供货任务。产品归档不会改变历史报价和订单。')+shot('07-products.png','产品卡片与图片预览'))
add('quotations','报价、版本与 PDF','07 / QUOTATIONS','<h3>创建一份报价</h3>'+steps(['从「报价 → 新建报价」、客户详情的「新建报价」或商机详情的「创建关联报价」进入。','选择客户与币种，填写报价有效期、贸易术语及指定地点、付款条件、交期与备注。','选择已建产品，或手动填写产品名称、规格与单位；逐行填写数量及销售单价。','点击「添加产品」增加明细，检查各项后点击「创建报价」。数量为整数，单价最多两位小数。'])+table(['状态 / 操作','使用方法'],[['草稿','打开报价点击「编辑草稿」，可修改产品、数量、单价和商务条款；关联客户不可在草稿编辑中更改。'],['已发送 / 待确认','在报价详情点击「更新状态」记录商务进度。系统不会替你发送邮件。'],['复制为新版本','客户要求改价、改规格或条款时，复制为新版本并修改。旧版继续保留。'],['下载 PDF','在报价详情点击「下载 PDF」，保存后自行通过邮件等方式发送给客户。'],['已转订单','原报价保留作为成交依据，不能再直接修改。']])+note('每份报价只使用一个币种，支持 USD、EUR、CNY、GBP。更改产品主资料不会回写历史报价。贸易术语应同时写明指定地点，例如 <code>FOB Ningbo</code>。')+shot('03-quotation.png','报价详情：产品明细、商务条件与版本操作'))
add('orders','确认订单与安排交期','08 / ORDERS',steps(['在已确认的报价详情点击「确认并转订单」，填写约定交期并创建订单。当前销售订单从报价生成。','打开「订单 → 查看订单」，核对客户、产品、数量、价格、商务条件与交期。','系统保存报价当时的明细和价格。相同报价重复执行转单不会创建第二笔相同订单。','点击「更新交期 / 状态」，按实际执行情况维护约定交期与业务状态。','合同、包装要求、物流资料及收款凭证可上传到订单附件。'])+table(['进度','由什么决定'],[['业务状态','负责人手动选择：待安排供货、供货执行中、待出货、已完成。新增供货任务会将状态改为供货执行中。'],['供货完成度','按各任务数量及完成百分比计算；尚未分配的数量仍会影响整体完成度。'],['收款进度','根据有效到账记录计算，作废记录不计入已收金额。'],['出货进度','根据各产品所有出货批次的实际数量累计计算。']])+note('供货、收款、出货分别跟踪。业务状态不会代替实际进度，也不会因为收齐款项或全部出货就自动改成「已完成」。完成履约后由负责人确认状态。')+shot('04-order.png','订单详情：产品、供货任务、收款与出货进度'))
add('supply','自产、外采与混合供货','09 / FULFILLMENT',steps(['管理员或负责业务员进入订单详情，在具体产品行点击「分配供货」。','选择自产或外采，填写本次数量、责任人、计划完成日期。外采还需要选择供应商。','同一产品可多次分配任务，但已分配数量合计不能超过订单产品数量。','采购 / 生产人员登录后，在「订单」或工作台查看自己的任务，点击「更新」。','填写完成进度 0–100%、质检结果 / 备注及计划完成日期；管理员也可以更新任务。'])+'<div class="example"><span class="tag">操作示例</span><h3>500 把椅子，300 把自产 + 200 把外采</h3><p>在同一条订单产品下，先创建数量 300 的自产任务，再创建数量 200 的外采任务。两个任务分别维护责任人、交期和进度。</p><p>如果自产完成 100%，外采完成 50%，该产品对应的数量加权完成度为 <strong>80%</strong>；多产品订单按订单全部产品数量继续汇总。</p></div>'+note('产品资料中的供货来源与订单内的执行任务相互独立。建立产品或供应商后，需要在订单内实际分配任务；产品数量分配完后，不应再次追加超过剩余数量的任务。供货任务成本按订单币种填写。'))
add('payments','定金、尾款与收款更正','10 / PAYMENTS',steps(['管理员或财务打开「收款与出货」，找到订单并点击「登记收款」；也可从订单详情进入。','核对订单币种与剩余应收，填写本次实际到账金额、到账日期和款项说明。','定金、阶段款、尾款分别登记。金额必须大于 0，且不超过订单剩余应收。','到账凭证可在订单详情的附件区上传，建议文件名包含到账日期和款项性质。','录错金额或订单时，在「收款与出货 → 收款记录」点击「更正 / 作废」，填写原因。作废后再重新登记正确记录。'])+'<div class="example"><span class="tag">金额示例</span><h3>订单 USD 10,000，先收 30% 定金</h3><p>第一次登记 <strong>USD 3,000</strong>，剩余应收为 <strong>USD 7,000</strong>；尾款实际到账后再登记 USD 7,000。</p></div>'+note('作废会保留原到账记录及原因，并重新计算余额。系统不自动读取银行流水，也不自动进行外币换算；登记的是人工核对后的实际款项。'))
add('shipments','按产品登记分批出货','11 / SHIPMENTS',steps(['管理员或负责业务员在「收款与出货」或订单详情点击「登记出货」。','填写提单 / 运单号、出货日期与目的地 / 港口。','在各产品行填写本批实际数量；本次不出的产品保持 0。','提交后，系统为本批出货保留记录，并累加各产品已出数量。数量不能超过剩余可出货数量。','下次出货继续新增批次；在订单详情的「出货批次」查看日期、物流号、目的地与数量。'])+note('例如订单 500 把椅子，本批出 200，把椅子的本次数量填 200；下一批再登记 300。第一版没有出货批次的界面编辑 / 作废入口，提交前请核对产品、数量和物流号。'))
add('reports','查看报表与理解口径','12 / REPORTS',table(['指标','统计口径'],[['订单金额、已收、待收','当前账号可访问订单的累计金额，按币种分别展示；作废到账不计入已收。'],['各阶段商机数量','当前可访问商机的实际阶段数量，包括赢单和丢单。'],['客户市场分布','按客户档案中的国家 / 地区统计客户数量。'],['按月订单金额','按订单创建月份及币种统计；月份以北京时间计算。']])+note('报表不是预测利润表。不同币种不直接相加，订单总额不等于已回款金额。财务角色不开放销售商机，因此其报表中的商机数量不代表公司全部商机。')+'<h3>建议的日常检查</h3><div class="check-grid"><div><b>每天开始</b><p>逾期跟进 → 今日待办 → 待收款 → 订单交期。</p></div><div><b>每次沟通后</b><p>记录反馈 → 更新商机 → 安排下一步和提醒日期。</p></div><div><b>每天结束</b><p>核对到账与出货 → 更新供货进度 → 执行备份。</p></div></div>')
add('import-files','CSV 导入导出与附件','13 / DATA & FILES','<h3>批量导入客户</h3>'+steps(['在「客户」点击「导出 CSV」，用导出的文件作为表头模板；按模板整理新客户资料。','保存为 UTF-8 编码的 CSV 文件，再点击「导入」选择文件。','每次 1–2000 行，至少填写公司名称。公司名称不区分大小写查重；重复公司跳过。','任何一行格式不合法时，整批导入撤销；修正后重新导入。导入成功会显示新增与跳过数量。','导入客户归当前操作人负责，管理员可再分配负责人。'])+'<pre><code>公司名称,国家,联系人,邮箱,客户类型,来源,关注产品\n示例客户有限公司,德国,Anna,anna@example.com,潜在客户,展会,户外家具</code></pre>'+note('客户类型使用「潜在客户」「正式客户」或「重点客户」。导出的是当前账号可访问的客户基础资料及首位联系人，不包含完整跟进、订单或附件；CSV 不能代替系统备份。')+'<h3>上传和下载附件</h3><p>在客户、产品或订单详情中，使用附件区域选择文件；上传成功后点击文件名下载。</p>'+table(['规则','说明'],[['文件格式','PDF、PNG、JPG、JPEG、WebP、CSV、XLSX、DOCX、TXT。'],['文件大小','单次请求不超过 10 MB，包含表单开销；建议文件略小于 10 MB。'],['产品图片','支持 PNG、JPEG、WebP，最多 2500 万像素；第一张图片用作卡片预览。'],['访问权限','按所属客户、产品或订单校验权限。采购 / 生产人员不能访问订单附件。'],['保存位置','文件保存在本机 instance/uploads；第一版不提供物理删除附件的界面入口。']]))
add('backup','启动、备份与恢复','14 / LOCAL OPERATIONS','<h3>启动与停止</h3><p>macOS 双击 <code>start.command</code> 启动；终端显示地址后打开浏览器。停止程序时，在启动终端按 <kbd>Ctrl</kbd> + <kbd>C</kbd>。重新启动不会清空数据。</p><h3>执行完整备份</h3>'+steps(['双击项目文件夹中的 <code>backup.command</code>。也可以在项目目录的终端执行下方备份命令。','等待看到「备份完成」及文件路径。结果位于 <code>backups/crm-日期时间.zip</code>。','备份包包含数据库、已登记附件和清单。建议每天结束工作后备份，并另存一份到其他磁盘。'])+'<pre><code>.venv/bin/python run.py backup</code></pre>'+note('备份可以在程序运行时执行。不要只复制运行中的 <code>crm.sqlite3</code> 代替完整备份；数据库运行时还可能存在 WAL 日志，附件也在单独目录。备份是手动执行的，系统没有自动定时备份。')+'<h3>从备份恢复</h3>'+steps(['先停止本地 CRM 服务。确认选中的是要恢复的完整备份包。','在项目目录的终端运行恢复命令，将示例路径替换为实际备份文件。','按提示输入 <code>RESTORE</code>。程序先校验备份，再保留恢复前副本、恢复数据库及附件。','恢复成功后双击 <code>start.command</code> 重启，并重新登录。旧会话会失效。'])+'<pre><code>.venv/bin/python run.py restore "backups/crm-日期时间.zip"</code></pre>'+note('<strong>恢复会将当前数据回退到备份时点。</strong>恢复前副本位于 <code>backups/before-restore-日期时间</code>。正式恢复前，请确认文件日期，必要时先做一次当前备份。','warn')+'<h3>忘记管理员密码</h3><p>在项目目录执行以下命令，按提示设置至少 10 位的新密码。输入密码时终端不显示字符。</p><pre><code>.venv/bin/python run.py reset-password admin</code></pre><h3>终端命令从哪里运行？</h3><p>打开「终端」，先输入 <code>cd </code>（末尾有空格），将项目文件夹拖入终端并回车，之后执行上述命令。Windows 用户将 <code>.venv/bin/python</code> 替换为 <code>.venv\\Scripts\\python</code>。</p>')
faqs=[('网页打不开怎么办？','确认 start.command 打开的终端还在运行，地址是 http://127.0.0.1:5001/。如果刚关机或关闭启动终端，请重新启动程序。不要同时启动两份服务占用同一个端口。'),('提示端口被占用怎么办？','先检查是否已有 CRM 终端在运行。如果确需换端口，在项目目录执行 .venv/bin/python run.py serve --port 5002，然后访问 http://127.0.0.1:5002/。'),('为什么看不到客户、菜单或某个按钮？','检查账号角色和客户负责人。业务员只看本人负责的客户；采购 / 生产只看分配给自己的订单产品和任务。管理员可查看或重新分配客户。'),('为什么还没有客户和订单？','正式数据库初始为空。先新建客户，再创建报价并转订单。说明中的界面截图使用独立测试数据，不会自动出现在正式系统。'),('为什么不能编辑已发送报价？','对外发送后的报价应使用“复制为新版本”进行调整。新版本是可编辑草稿，旧报价继续保留。已转订单报价不能直接修改。'),('为什么报价不能选到某个客户？','报价客户选项只包含未归档客户。先在客户列表的“已归档”中恢复该客户，再创建报价。'),('为什么无法再次分配供货？','检查该产品订单数量及已分配数量。同一订单产品的全部供货任务数量合计不能超过订单数量；不要将包装配件当作同一产品额外数量重复分配。'),('为什么无法收款或出货？','先检查角色权限，再核对剩余应收或剩余产品数量。收款不能超过剩余应收；本批出货数量不能超过各产品的剩余数量。'),('系统会自动发邮件或同步 WhatsApp 吗？','当前版本手动记录沟通。报价 PDF 需要自行发送，系统不自动收发邮件、不同步 WhatsApp，也不自动读取银行流水。'),('换浏览器或清理浏览器缓存会删除数据吗？','业务数据保存在本机数据库及附件目录，不在浏览器缓存中。清理缓存后可能需要重新登录；不要删除项目中的 instance 文件夹。'),('同事可以从另一台电脑打开这个地址吗？','不能。127.0.0.1 始终指访问者自己的电脑，当前版本按本机部署运行。如以后需要局域网共享，应另行配置服务访问和部署方式。'),('关闭页面前需要点击“保存全部”吗？','没有“保存全部”。每次表单提交成功后即保存。未点击保存 / 创建、或出现错误提示的内容尚未保存；处理错误后再次提交。'),('提示会话校验失败怎么办？','刷新页面后重新操作，必要时退出再登录。同一浏览器中切换了账号或会话过期时，旧标签页需要刷新。'),('哪些数据不能从界面直接更正或删除？','客户可归档与恢复；收款可作废并重录。当前没有出货批次编辑 / 作废、供货任务数量调整 / 删除、订单产品金额修改和附件物理删除的界面入口。出现这类录入问题时先保留记录并联系维护人员处理，不要直接修改 SQLite 文件。')]
add('faq','常见问题与使用边界','15 / HELP',''.join(f'<details class="faq"><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in faqs)+note('当前版本适合本地外贸业务管理；不含完整库存、生产排程、自动汇率、邮件营销和在线协同访问。指南依据当前实际功能编写，后续程序升级后应同步更新。'))
css='''
:root{--blue:#5548dd;--navy:#202944;--ink:#303950;--muted:#7b8499;--line:#e6e9f1;--bg:#f6f7fb}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:28px}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.9 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}button,input{font:inherit}button{cursor:pointer;padding:9px 16px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink)}button:hover{border-color:#a59ce8}.primary{background:var(--blue);color:white;border-color:var(--blue)}aside{position:fixed;left:0;top:0;bottom:0;width:245px;background:white;border-right:1px solid var(--line);padding:30px 21px;overflow:auto}.brand{font-size:23px;font-weight:750;letter-spacing:2px;color:var(--navy);display:flex;gap:12px;align-items:center}.logo{background:var(--blue);color:#fff;width:35px;height:35px;display:grid;place-items:center;border-radius:10px;letter-spacing:0}.brand small{display:block;font-size:9px;color:#919ab0;letter-spacing:2px;line-height:1.5}.side-label{margin:24px 10px 12px;color:#a0a7b6;font-size:11px;letter-spacing:2px}.search{width:100%;border:1px solid var(--line);border-radius:7px;padding:10px 12px;outline-color:var(--blue);font-size:12px;margin:22px 0 2px}nav a{display:flex;gap:12px;align-items:center;color:#768096;font-size:12px;padding:9px 10px;border-radius:6px;margin:2px 0;line-height:1.6}nav a.active{background:#eeecff;color:var(--blue);font-weight:650}nav a span{font-size:10px;color:#a5aabd}aside footer{font-size:10px;color:#a3aabc;border-top:1px solid var(--line);margin:22px 10px 0;padding-top:15px;line-height:1.8}main{margin-left:245px;padding:30px 44px 70px;max-width:1550px}.topline{display:flex;justify-content:space-between;align-items:center;margin-bottom:23px;font-size:12px;color:var(--muted)}.tools{display:flex;gap:9px}.hero{background:var(--navy);color:white;border-radius:16px;padding:45px 42px;position:relative;overflow:hidden;margin-bottom:24px}.hero:after{content:'';position:absolute;right:-80px;top:-95px;width:400px;height:400px;border:70px solid #ffffff05;border-radius:50%;pointer-events:none}.eyebrow{font-size:11px;letter-spacing:3px;color:#aba4f8;font-weight:600}.hero h1{font-size:36px;margin:12px 0 10px;letter-spacing:-1px;line-height:1.5}.hero p{max-width:650px;color:#bcc4db;font-size:14px;margin:0}.hero-tags{display:flex;gap:10px;margin-top:23px;flex-wrap:wrap}.hero-tags span{padding:4px 10px;border-radius:5px;background:#ffffff0b;border:1px solid #ffffff0a;color:#cdd2e8;font-size:11px}.intro-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:26px}.intro{background:white;border:1px solid var(--line);padding:21px;border-radius:10px}.intro b{font-size:13px;display:block;color:var(--navy)}.intro p{margin:7px 0 0;font-size:12px;color:var(--muted);line-height:1.9}.chapter{background:white;border:1px solid var(--line);border-radius:12px;padding:32px 36px;margin-bottom:23px;scroll-margin-top:25px}.chapter .kicker{color:#9b91d5;font-size:10px;letter-spacing:2px;font-weight:650}.chapter h2{font-size:23px;line-height:1.5;color:var(--navy);margin:7px 0 22px}.chapter h3{font-size:16px;color:var(--navy);margin:25px 0 12px}.chapter p{font-size:14px;margin:12px 0}.lead{color:#737e94;font-size:15px!important}.flow{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:22px 0 25px}.flow span{padding:8px 13px;border:1px solid #e4e0fc;border-radius:7px;background:#f8f7ff;color:#7566c4;font-size:12px}.flow b{font-size:12px;color:#b8b4cd}.flow.small span{font-size:11px;padding:7px 10px}.steps{counter-reset:step;list-style:none;padding:0;margin:18px 0}.steps li{position:relative;padding-left:40px;margin:16px 0;font-size:14px}.steps li:before{counter-increment:step;content:counter(step,decimal-leading-zero);position:absolute;left:0;top:1px;font-size:11px;font-weight:600;background:#f0edff;color:#8070cd;width:27px;height:27px;border-radius:7px;display:grid;place-items:center;line-height:1}.callout{border-radius:8px;padding:15px 18px;background:#f5f3ff;border-left:3px solid #ac9fe6;color:#78699e;margin:21px 0;font-size:12px;line-height:1.9}.callout.warn{background:#fff7e9;color:#9d7a41;border-color:#e4c48c}.table-wrap{overflow:auto;margin:17px 0}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left;min-width:450px}th{background:#f6f7fb;color:#8a92a5;font-weight:500;padding:11px 15px}td{padding:13px 15px;border-bottom:1px solid #eef0f5;vertical-align:top}td:first-child{min-width:120px;color:#59617a;font-weight:550}code,kbd{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.87em;background:#f0f1f6;padding:2px 5px;border-radius:4px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f6fa;border:1px solid var(--line);padding:17px 20px;border-radius:8px;font-size:12px;line-height:1.9}pre code{background:none;padding:0;font-size:1em}kbd{border:1px solid #e2e5ed;font-size:11px}.example{background:#fafbfe;border:1px dashed #deddeb;border-radius:9px;padding:20px 23px;margin:22px 0}.example .tag{color:#9286c5;font-size:10px;letter-spacing:2px}.example h3{margin-top:7px}.example p{font-size:12px}.shot{border:1px solid var(--line);border-radius:8px;margin:25px 0 0}.shot summary{padding:12px 17px;cursor:pointer;color:#7e73ae;font-size:12px;background:#faf9ff;border-radius:8px}figure{margin:0;padding:15px}figure img{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:5px}figcaption{font-size:10px;color:#969db0;margin-top:10px}.faq{padding:15px 0;border-bottom:1px solid var(--line)}.faq summary{font-size:14px;cursor:pointer;color:#4c5570;font-weight:550}.faq p{padding-left:18px;color:#80899b;font-size:13px}.check-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.check-grid>div{padding:17px;background:#f8f9fc;border-radius:8px}.check-grid b{font-size:13px;color:#7566c2}.check-grid p{font-size:12px;color:#8b94a6}.bottom{color:#9ca4b5;font-size:11px;text-align:center;margin-top:35px}.noresults{display:none;padding:45px;text-align:center;color:#8991a5}.progress{position:fixed;top:0;left:245px;right:0;height:3px;z-index:10}.progress i{display:block;background:#8f82e2;height:100%;width:0}.screen-only{display:block}[hidden]{display:none!important}@media(min-width:1600px){main{margin-left:calc(245px + (100vw - 1550px)/2);max-width:1305px}}@media(max-width:1000px){aside{width:210px;padding:25px 15px}main{margin-left:210px;padding:25px}.chapter{padding:26px}.hero{padding:32px}.hero h1{font-size:29px}.progress{left:210px}}@media(max-width:700px){aside{position:relative;width:100%;height:auto;padding:21px;border-bottom:1px solid var(--line)}aside .side-label,aside footer{display:none}nav{display:flex;gap:7px;overflow:auto;white-space:nowrap}nav a{flex-shrink:0;background:#f7f7fc;padding:8px 11px}.search{margin:18px 0 10px}main{margin:0;padding:22px 16px}.hero{padding:27px 24px}.hero h1{font-size:27px}.chapter{padding:23px 21px}.chapter h2{font-size:21px}.intro-grid,.check-grid{grid-template-columns:1fr}.intro-grid{gap:9px}.intro{padding:15px 20px}.intro p{margin:4px 0 0}.topline{align-items:start;gap:10px}.topline>span{font-size:10px}.tools{gap:5px}.tools button{padding:7px 9px;font-size:11px}.tools a button{white-space:nowrap}.progress{left:0}td,th{padding:11px}.steps li{font-size:13px}.hero-tags span{font-size:10px}}@media print{@page{size:A4;margin:16mm}body{background:white;font-size:11pt;color:#222}aside,.topline,.progress,.noresults,.intro-grid,.bottom{display:none!important}main{margin:0;padding:0;max-width:none}.hero{background:white;color:#202944;border:0;padding:0 0 15px;page-break-after:avoid}.hero:after{display:none}.hero h1{font-size:27pt}.hero p,.eyebrow{color:#666}.hero-tags{display:none}.chapter{border:0;border-top:1px solid #ccc;border-radius:0;padding:20px 0;margin:0;display:block!important}.chapter h2{font-size:17pt;page-break-after:avoid}.chapter h3{page-break-after:avoid}.steps li,.callout,tr{break-inside:avoid}.shot{display:none}.faq p{display:block!important}.faq:not([open])>p{display:block!important}.flow span,th,.callout{background:#f7f7f7!important;color:#333}.table-wrap{overflow:visible}table{min-width:0}a{color:inherit}pre{white-space:pre-wrap}.check-grid{grid-template-columns:1fr 1fr 1fr}button{display:none}code{word-break:break-word}}
'''
nav=''.join(f'<a href="#{id}" data-id="{id}"><span>{i:02}</span>{title}</a>' for i,(id,title,k,c) in enumerate(sections,1))
content=''.join(f'<section class="chapter" id="{id}"><div class="kicker">{k}</div><h2>{title}</h2>{c}</section>' for id,title,k,c in sections)
script='''const search=document.querySelector('#search'),chapters=[...document.querySelectorAll('.chapter')],links=[...document.querySelectorAll('nav a')];function filterGuide(){const q=search.value.trim().toLocaleLowerCase();let count=0;chapters.forEach(c=>{let match=!q||c.textContent.toLocaleLowerCase().includes(q);c.hidden=!match;if(match)count++;document.querySelector('nav a[data-id="'+c.id+'"]').hidden=!match});document.querySelector('#noresults').style.display=count?'none':'block';document.querySelector('#resultCount').textContent=q?count+' 个相关章节':'离线使用 · 支持打印';}search.addEventListener('input',filterGuide);search.addEventListener('keydown',e=>{if(e.key==='Escape'){search.value='';filterGuide()}});const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.dataset.id===e.target.id))}})},{rootMargin:'-10% 0px -60% 0px'});chapters.forEach(c=>observer.observe(c));window.addEventListener('scroll',()=>{let max=document.documentElement.scrollHeight-innerHeight;document.querySelector('#progress').style.width=(max>0?scrollY/max*100:100)+'%'},{passive:true});document.querySelector('#print').addEventListener('click',()=>{search.value='';filterGuide();window.print()});'''
html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="远帆本地外贸 CRM 使用指南：客户、商机、报价、订单、供货、收款出货与备份恢复。"><title>远帆 CRM · 使用指南</title><link rel="icon" href="data:,"><style>{css}</style></head><body><div class="progress"><i id="progress"></i></div><aside><div class="brand"><span class="logo">➤</span><div>远帆<small>YUANFAN · USER GUIDE</small></div></div><input id="search" class="search" type="search" placeholder="搜索指南，如：收款、备份" aria-label="搜索使用指南"><div class="side-label">CONTENTS / 使用目录</div><nav aria-label="指南章节">{nav}</nav><footer>适用：当前本地部署版本<br>更新日期：2026 年 10 月 13 日<br>本文件可独立保存、离线打开</footer></aside><main><div class="topline"><span id="resultCount" role="status" aria-live="polite">离线使用 · 支持打印</span><div class="tools"><button id="print">打印 / 保存 PDF</button><a href="http://127.0.0.1:5001/" target="_blank" rel="noopener"><button class="primary">打开本地 CRM ↗</button></a></div></div><header class="hero"><div class="eyebrow">YOUR DAILY TRADE WORKSPACE</div><h1>远帆 CRM 使用指南</h1><p>从第一个客户，到每一笔订单的收款与出货。<br>按实际工作顺序，掌握本地外贸业务管理。</p><div class="hero-tags"><span>Python + SQLite 本地版</span><span>15 个操作章节</span><span>含真实界面示例</span></div></header><div class="intro-grid"><div class="intro"><b>第一次使用</b><p>从「第一次使用」开始，建立客户，再完成一份报价。</p></div><div class="intro"><b>按岗位查阅</b><p>业务员看客户与报价，采购生产看供货，财务看收款。</p></div><div class="intro"><b>日常维护</b><p>启动与备份操作集中在第 14 章，常见问题在第 15 章。</p></div></div><div id="noresults" class="noresults" role="status">没有匹配章节，请换一个关键词。</div>{content}<div class="bottom">远帆 CRM · 本地使用指南　/　2026.10.13<br>截图为独立测试数据。本指南不包含账号密码或正式客户资料。</div></main><script>{script}</script></body></html>'''
out=ROOT/'远帆CRM-使用指南.html';out.write_text(html,encoding='utf-8')
(ROOT/'app'/'static'/'guide.html').write_text(html,encoding='utf-8')
print(f'Created {out.name}: {out.stat().st_size:,} bytes, {len(sections)} chapters')
